-- name: ListNotes :many
SELECT id, body, place_room, place_row, shelf_code, title, written_on, created_at, created_by_user_id, created_by_user_nameid, last_modified_at, last_modified_by_user_id, last_modified_by_user_nameid, is_deleted
FROM notes
WHERE (sqlc.narg(shelf_code)::VARCHAR(12) IS NULL OR shelf_code = sqlc.narg(shelf_code))
  AND (sqlc.narg(written_on)::DATE IS NULL OR written_on = sqlc.narg(written_on))
  AND (sqlc.narg(search)::text IS NULL
       OR position(lower(sqlc.narg(search)) in lower(title)) > 0
       OR position(lower(sqlc.narg(search)) in lower(body)) > 0)
  AND is_deleted = false
ORDER BY CASE WHEN sqlc.arg(sort)::text = 'written_on' THEN written_on END ASC,
    CASE WHEN sqlc.arg(sort)::text = '-written_on' THEN written_on END DESC,
    CASE WHEN sqlc.arg(sort)::text = 'title' THEN title END ASC,
    CASE WHEN sqlc.arg(sort)::text = '-title' THEN title END DESC,
    id
LIMIT sqlc.arg(page_size) OFFSET sqlc.arg(page_offset);

-- name: ListNotesTotal :one
SELECT count(*) AS total
FROM notes
WHERE (sqlc.narg(shelf_code)::VARCHAR(12) IS NULL OR shelf_code = sqlc.narg(shelf_code))
  AND (sqlc.narg(written_on)::DATE IS NULL OR written_on = sqlc.narg(written_on))
  AND (sqlc.narg(search)::text IS NULL
       OR position(lower(sqlc.narg(search)) in lower(title)) > 0
       OR position(lower(sqlc.narg(search)) in lower(body)) > 0)
  AND is_deleted = false;

