-- name: AmendNote :one
UPDATE notes
SET body = coalesce(sqlc.narg(body), body),
    place_room = coalesce(sqlc.narg(place_room), place_room),
    place_row = coalesce(sqlc.narg(place_row), place_row),
    shelf_code = coalesce(sqlc.narg(shelf_code), shelf_code),
    title = coalesce(sqlc.narg(title), title),
