    last_modified_by_user_id = sqlc.arg(last_modified_by_user_id),
    last_modified_by_user_nameid = sqlc.arg(last_modified_by_user_nameid)
WHERE id = sqlc.arg(id)
  AND is_deleted = false
RETURNING id, body, place_room, place_row, shelf_code, title, written_on, created_at, created_by_user_id, created_by_user_nameid, last_modified_at, last_modified_by_user_id, last_modified_by_user_nameid, is_deleted;
